<section class="page-hero path-builder-hero"><div class="container"><nav class="breadcrumbs"><a href="<?= e(url('service/'.$service['slug'])) ?>"><?= e($service['name']) ?></a><span>/</span><span>أنشئ مسارك</span></nav><span class="eyebrow">أنشئ مسارك الذكي</span><h1>أجب عن أسئلة قصيرة، وسنعرض الخطوات المناسبة لحالتك فقط.</h1><p>القواعد معتمدة مسبقًا ولا ينشئ النظام شروط أهلية جديدة من تلقاء نفسه.</p></div></section>
<section class="section"><div class="container path-builder-grid"><div><form class="wizard-card" method="get" action="<?= e(url('path/'.$service['slug'])) ?>" data-smart-path-form><?php foreach($questions as $i=>$q): ?><fieldset class="wizard-question"><legend><span><?= $i+1 ?></span><?= e($q['question_text']) ?></legend><div class="option-grid"><?php foreach($q['options'] as $opt): ?><label class="choice-card"><input type="radio" name="<?= e($q['question_key']) ?>" value="<?= e($opt['option_key']) ?>" <?= (($answers[$q['question_key']]??'')===$opt['option_key'])?'checked':'' ?> <?= (int)$q['is_required']===1?'required':'' ?>><span><?= e($opt['label']) ?></span></label><?php endforeach; ?></div></fieldset><?php endforeach; ?><button class="btn btn-primary btn-lg" type="submit" data-track-event="smart_path_complete">عرض مساري</button></form></div><aside><div class="sticky-card"><span class="eyebrow">ماذا سيحدث؟</span><div class="mini-feature"><b>1</b><span>نطبق قواعد المسار المعتمدة</span></div><div class="mini-feature"><b>2</b><span>نخفي الخطوات غير المنطبقة</span></div><div class="mini-feature"><b>3</b><span>نوضح أي خطوة مانعة ومخرجها المطلوب</span></div></div></aside></div></section>
<?php if($answers): ?><section class="section section-tint" id="result"><div class="container"><div class="section-head"><div><span class="eyebrow">مسارك الشخصي</span><h2><?= count($steps) ?> خطوات تنطبق على إجاباتك</h2></div><a class="text-link" href="<?= e(url('service/'.$service['slug'])) ?>">عرض المسار العام</a></div><div class="timeline personalized"><?php foreach($steps as $step): ?><article class="timeline-item <?= $step['blocked']?'is-blocked':'' ?>"><div class="timeline-index"><?= (int)$step['position'] ?></div><div class="timeline-card"><div class="timeline-top"><div><h3><?= e($step['title']) ?></h3><span><?= e($step['entity']) ?></span></div><?php if($step['blocked']): ?><span class="badge badge-warn">🔒 مانعة</span><?php else: ?><span class="badge badge-success">متاحة</span><?php endif; ?></div><?php if($step['blocked'] && $step['prerequisite']): ?><div class="dependency-box warning"><b>المطلوب لفتح هذه الخطوة</b><p><?= e($step['prerequisite']) ?></p></div><?php endif; ?><div class="step-grid"><div><small>ما الذي ستفعله؟</small><p><?= e($step['action_text']) ?></p></div><div><small>ما المخرج؟</small><p><?= e($step['output_text']) ?></p></div></div><div class="step-actions"><?php if(\Khatauat\Core\Auth::check()): ?><form method="post" action="<?= e(url('account/step/toggle')) ?>"><?= csrf_field() ?><input type="hidden" name="service_id" value="<?= (int)$service['id'] ?>"><input type="hidden" name="step_id" value="<?= (int)$step['id'] ?>"><input type="hidden" name="answers_json" value="<?= e(json_encode($answers, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?>"><input type="hidden" name="return_to" value="<?= e(ltrim(current_url_path(),'/').'?'.http_build_query($answers).'#result') ?>"><button class="btn <?= $step['completed']?'btn-soft':'btn-ghost' ?>" type="submit"><?= $step['completed']?'✓ تم الإنجاز':'تحديد كمُنجزة' ?></button></form><?php endif; ?><a class="btn btn-official" href="<?= e($step['official_url']) ?>" target="_blank" rel="noopener nofollow" data-track="official-outbound" data-service-id="<?= (int)$service['id'] ?>" data-service-name="<?= e($service['name']) ?>">تنفيذ الخطوة رسميًا ↗</a></div></div></article><?php endforeach; ?></div><div class="result-actions"><?php if(\Khatauat\Core\Auth::check()): ?><form method="post" action="<?= e(url('path/'.$service['slug'].'/save')) ?>"><?= csrf_field() ?><?php foreach($answers as $k=>$v): ?><input type="hidden" name="<?= e($k) ?>" value="<?= e($v) ?>"><?php endforeach; ?><button class="btn btn-primary" type="submit" data-track-event="path_save">حفظ المسار في حسابي</button></form><?php else: ?><a class="btn btn-primary" href="<?= e(url('login')) ?>">سجّل الدخول لحفظ المسار</a><?php endif; ?><a class="btn btn-ghost" href="<?= e(url('export/'.$service['slug'].'/pdf?'.http_build_query($answers))) ?>" data-track-event="path_export">تنزيل PDF</a><a class="btn btn-ghost" href="<?= e(url('export/'.$service['slug'].'/print?'.http_build_query($answers))) ?>" target="_blank" data-track-event="path_export">طباعة</a></div></div></section><?php endif; ?>
